import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Purchases, fees and payouts","description":"","frontmatter":{},"headers":[],"relativePath":"user/admin/payments-payouts.md","filePath":"user/admin/payments-payouts.md"}'),s={name:"user/admin/payments-payouts.md"};function o(d,e,l,i,c,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="purchases-fees-and-payouts" tabindex="-1">Purchases, fees and payouts <a class="header-anchor" href="#purchases-fees-and-payouts" aria-label="Permalink to &quot;Purchases, fees and payouts&quot;">​</a></h1><h2 id="purchases" tabindex="-1">Purchases <a class="header-anchor" href="#purchases" aria-label="Permalink to &quot;Purchases&quot;">​</a></h2><p><strong>Purchases</strong> lists everything clients bought, across all centers. Open one to see its items, payments, discounts and <strong>financials</strong> (fee, platform subsidy and what the center earns). You can export the list.</p><table tabindex="0"><thead><tr><th>Purchase status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Pending</strong></td><td>Created, not paid or confirmed yet</td></tr><tr><td><strong>Confirmed</strong></td><td>Paid in full (or cash on arrival accepted)</td></tr><tr><td><strong>Completed</strong></td><td>Fulfilled</td></tr><tr><td><strong>Cancelled</strong></td><td>Stopped; refunds follow the rules below</td></tr></tbody></table><p>A purchase becomes confirmed only when its successful payments add up to the full total. A failed payment can be retried; each try is a new payment record.</p><h2 id="platform-fees" tabindex="-1">Platform fees <a class="header-anchor" href="#platform-fees" aria-label="Permalink to &quot;Platform fees&quot;">​</a></h2><p>The <strong>platform fee</strong> is what a center owes the platform on a sale. It does <strong>not</strong> change what the client pays. Manage fee rules under <strong>Fees</strong> (you need the fee permission).</p><p>A rule can be percentage, fixed amount, or both, with a minimum and maximum. The first matching rule wins, in this order: the center&#39;s rule for the channel, the platform rule for the channel, the center&#39;s fallback, the platform fallback. Each channel (client app, center app, web, center dashboard) can have its own rule.</p><p>The fee is recorded once per sale and <strong>reversed</strong> if the purchase is cancelled or fully refunded. A partial refund keeps the fee.</p><h2 id="center-ledger-and-payouts" tabindex="-1">Center ledger and payouts <a class="header-anchor" href="#center-ledger-and-payouts" aria-label="Permalink to &quot;Center ledger and payouts&quot;">​</a></h2><p>Every online payment adds to the center&#39;s <strong>ledger</strong>. After a hold period it becomes available. Fees, refunds and discounts funded by the platform adjust the balance. <strong>Cash and manual payments stay with the center</strong> and are not paid out.</p><p>Once a week (Sunday, 00:00 UTC) the platform creates one <strong>pending payout</strong> per center for its available balance. A center is skipped when its balance is zero or negative, or when it has <strong>no bank account</strong> set; its balance carries to the next run.</p><p>Under <strong>Payouts</strong> you can open a payout, <strong>mark it paid</strong> after transferring the money (the center is notified), or <strong>cancel</strong> it. You can export a center&#39;s ledger from the center page.</p>',13)])])}const f=t(s,[["render",o]]);export{u as __pageData,f as default};
